from pathlib import Path
import collections, hashlib, json
from datetime import datetime, timezone
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1]
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def write(n,x):(HERE/n).write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
q=read(HERE/'EXPANDED_SUPPLY_QUEUE.json');s=q['summary']
receipts=[read(p) for p in sorted((HERE/'OwnedPackSources').glob('*/SOURCE_RECEIPT.json'))]
groups=collections.defaultdict(list)
for r in q['rows']:groups[(r['category'],r['source_pack'])].append(r)
batches=[]
for (category,pack),rows in groups.items():
 for start in range(0,len(rows),32):
  part=rows[start:start+32];batches.append({'batch_id':'BANK_EXPANSION_'+str(len(batches)+1).zfill(3),'category':category,'source_pack':pack,'count':len(part),'asset_ids':[r['asset_id'] for r in part],'state':'PROPOSED_NATIVE_LEASE_REQUIRED','imported':0,'reused_applied':0,'failed_imports':0,'pending':len(part),'receipt_required_fields':['asset_path','source','licence_basis','triangles','LODs','collision','materials_bound','textures_resolved','named_saved_packages','reopen_result'],'receipt_policy':'One actual receipt per executed batch; isolate failures and continue remaining authorized items. Do not force-save failed buffers.'})
write('EXPANDED_BATCH_MANIFEST.json',{'batches':batches,'shared_dependencies':'Resolve and reuse once per source pack; native closure remains mandatory.','selection_and_profile_changes':False,'native_execution_started':False})
last=(ROOT/'Staging/ModelBank/EDITOR_OWNER.txt').read_text().splitlines()[-1]
baseline=read(HERE/'PRESERVATION_CHECK.json')['after']
current={p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in baseline}
write('EXPANSION_PRESERVATION_CHECK.json',{'utc':datetime.now(timezone.utc).isoformat(),'baseline':baseline,'current':current,'shared_files_unchanged':baseline==current,'last_owner_line':last,'manager_lease_received':False,'editor_calls':0,'vendor_writes':0,'assignments_writes':0,'area_profile_writes':0,'catalog_writes':0,'selection_enablements':0,'road_candidate_writes':0,'output_scope':str(HERE)})
download_files=sum(len(r['files']) for r in receipts);download_bytes=sum(r['source_bytes'] for r in receipts)
text=['EXPANDED ASSET BANK SUPPLY — 2026-10-06','Manager: Claude Code cc37d4d2-3d62-4f53-b689-28432b5527ae','','Outcome',f"Expanded from 60 to {s['model_candidates']} model candidates across {len(s['source_packs'])} source packs. {len(receipts)} newly owned packs were downloaded into retained operator staging and their {download_files} source/dependency files ({download_bytes/1e9:.2f} GB) verified against the acquisition manifests.",f"{s['existing_canonical_ids_reused']} existing catalogue identities retained; {s['new_candidate_ids']} proposed new identities. {s['quality_alternatives_not_counted_twice']} quality variants are retained as alternatives and do not count twice.",'Imported into Unreal this run: 0. Registered in DT_EnvironmentBank_v4 this run: 0. Native triangle/LOD/collision/material/texture readiness is pending the manager-issued editor lease. Source files are available; they are not yet a usable native-bank delivery.','','Counts by proposed category']
text += [f'- {k}: {v}' for k,v in s['categories'].items()]
text+=['','Source packs represented']+[f'- {k}: {v} model candidates' for k,v in s['source_packs'].items()]
text+=['','New source downloads']+[f"- {r['title']}: {len(r['files'])} verified files; SOURCE_RECEIPT.json under OwnedPackSources/{r['pack']}." for r in receipts]
text+=['','Variety and limits','- Greasewood, Phoenix canariensis palms, giant reed, desert shrubs/rocks and Namaqualand foliage/rocks supplement existing palms, MOUT desert trees/shrubs, alder, birch and maple. Individual variants include size/form/condition differences, not necessarily different botanical species.','- Namaqualand LP/NN versions are grouped per geometry name. Phoenix shared add-on grass/bush assets are not counted as new palm varieties. Existing bank IDs and initial supplier IDs are retained.','- Models are selected by manifest/path/name and retained catalogue evidence. Native class, measured dimensions and material readiness still need editor inspection. Candidate counts are not verified mesh usability.','- Native style and regional ecology remain manager decisions. Source species from other regions are not automatically approved for Gaza or Iran.','- Street props include signs, poles, benches, bins, fences, awnings, AC units, antennas, tanks, barriers and clutter. Hosted props require consumer mapping; source availability does not create the missing placement consumer.','- Existing 87 road candidates are untouched. Downloaded packs may contain vendor road/support files; none is registered or approved as a road candidate.','- Complete vehicles and further owned packs remain outside this expansion execution. The acquisition cache is not a claim that every owned pack has been downloaded.','','Licence and authority','Aviv confirmed that licences exist and requested more models from newly acquired assets. This confirmation is recorded in OWNER_CONFIRMATION_AND_SCOPE_UPDATE.json and accepted for technical source preparation. Ownership is not being requested again.','The later provenance reply says the owner will verify acquisition-specific licence text in Fab Library. Exact document identification remains separate; no licence category was fabricated and no existing hold was released.','Latest editor owner line:',last,'OWNER=NONE is not a lease. No PID-bound lease for this operator has been received. The original one-writer instruction still requires Claude to issue it through Aviv before editor inspection/import/registration/saves.','','Execution proposal',f"{len(batches)} proposed batches of at most 32 candidates, grouped by source pack/category. Each executed batch must produce its own actual receipt; templates/proposals are not import receipts.",'EXPANDED_SUPPLY_QUEUE.json contains exact IDs, source paths, hashes, bank-only destinations and dependency leads. EXPANDED_CATALOG_PATCH_PROPOSAL.json preserves existing runtime rows verbatim; all proposed new rows are held and disabled.','Before execution: re-read last owner line, confirm lease/PID/world/dirty state; resolve full native dependency closure; verify source-to-bank remapping; reuse existing assets; measure native fields; save only named bank packages; record per-asset success/failure; submit catalogue/selection proposals separately.','No source project is launched, no vendor asset overwritten, and no profile/catalog pin is changed by these scripts.','','Preservation',f'Shared catalogue/table/workflow/assignment file hashes unchanged versus first inventory snapshot: {baseline==current}. All current writes are in this operator staging directory.','','Short Hebrew summary for Aviv',f"ההצעה הורחבה מ־60 ל־{s['model_candidates']} מועמדים, כולל חמש חבילות חדשות שהורדו ואומתו. אישור הרישיונות שלך נרשם. עדיין לא בוצע ייבוא ל־Unreal; נדרשת הקצאת עורך כתובה מהמנהל."]
(HERE/'EXPANSION_REPORT.txt').write_text('\n'.join(text)+'\n',encoding='utf-8')
write('EXPANSION_DELIVERY.json',{'utc':datetime.now(timezone.utc).isoformat(),'model_candidates':s['model_candidates'],'newly_downloaded_packs':len(receipts),'source_files_verified':download_files,'source_bytes_verified':download_bytes,'native_imports':0,'native_registrations':0,'batch_count':len(batches),'manager_lease_received':False,'shared_files_unchanged':baseline==current})
print(json.dumps({'models':s['model_candidates'],'packs_downloaded':len(receipts),'verified_files':download_files,'source_GB':round(download_bytes/1e9,2),'batches':len(batches),'shared_unchanged':baseline==current}))
